items.potential:
OR = {
	has_edict = sacrifice_dutiful_1
	get_tenet_tier = {
		tenet = tenet_sacrifism
		value = 1
	}
}
is_death_cult_empire = no

items.effect:
hidden_effect = {
	set_variable = {
		which = pops_to_sacrifice
		value = 600
	}
	if = {
		limit = {
			is_variable_set = pops_to_sacrifice
		}
		while = {
			count = pops_to_sacrifice
			limit = {
				check_variable = {
					which = pops_to_sacrifice
					value > 0
				}
			}
			if = {
				limit = {
					any_owned_pop_group = {
						pop_group_size > prev.pops_to_sacrifice
					}
				}
				random_owned_pop_group = {
					limit = {
						pop_group_size > prev.pops_to_sacrifice
					}
					sacrifice_pop_group = {
						pop_group = this
						amount = prev.pops_to_sacrifice
					}
				}
				set_variable = {
					which = pops_to_sacrifice
					value = 0
				}
			}
			else = {
				ordered_owned_pop_group = {
					position = 0
					order_by = trigger:pop_group_size
					export_trigger_value_to_variable = {
						trigger = pop_group_size
						variable = sacrificed_pops
					}
					change_variable = {
						which = sacrificed_pops
						value = -1
					}
					sacrifice_pop_group = {
						pop_group = this
						amount = sacrificed_pops
					}
					multiply_variable = {
						which = sacrificed_pops
						value = -1
					}
					prev = {
						change_variable = {
							which = pops_to_sacrifice
							value = prev.sacrificed_pops
						}
					}
				}
			}
		}
	}
}

